#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

const string BASE =
    "What are you doing at the end of the world? Are you busy? Will you save us?";
const string PREFIX =
    "What are you doing while sending \"";
const string MIDDLE =
    "\"? Are you busy? Will you send \"";
const string SUFFIX = "\"?";
const int64 LIMIT = 4'000'000'000'000'000'000LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    vector<pair<int, int64>> queries(q);
    int maxN = 0;

    for (auto &[n, pos] : queries) {
        cin >> n >> pos;
        maxN = max(maxN, n);
    }

    vector<int64> length(maxN + 1);
    length[0] = BASE.size();

    for (int i = 1; i <= maxN; ++i) {
        i128 value = static_cast<i128>(PREFIX.size()) +
                     static_cast<i128>(MIDDLE.size()) +
                     static_cast<i128>(SUFFIX.size()) +
                     2 * static_cast<i128>(length[i - 1]);
        length[i] = value > LIMIT ? LIMIT : static_cast<int64>(value);
    }

    string answer;

    for (auto [n, pos] : queries) {
        if (pos > length[n]) {
            answer += '.';
            continue;
        }

        while (n > 0) {
            if (pos <= static_cast<int64>(PREFIX.size())) {
                answer += PREFIX[pos - 1];
                break;
            }
            pos -= PREFIX.size();

            if (pos <= length[n - 1]) {
                --n;
                continue;
            }
            pos -= length[n - 1];

            if (pos <= static_cast<int64>(MIDDLE.size())) {
                answer += MIDDLE[pos - 1];
                break;
            }
            pos -= MIDDLE.size();

            if (pos <= length[n - 1]) {
                --n;
                continue;
            }
            pos -= length[n - 1];

            if (pos <= static_cast<int64>(SUFFIX.size())) {
                answer += SUFFIX[pos - 1];
            } else {
                answer += '.';
            }
            break;
        }

        if (n == 0) {
            answer += pos <= static_cast<int64>(BASE.size()) ? BASE[pos - 1] : '.';
        }
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

const string base =
    "What are you doing at the end of the world? Are you busy? Will you save us?";
const string prefix = "What are you doing while sending \"";
const string middle = "\"? Are you busy? Will you send \"";
const string suffix = "\"?";

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    vector<pair<int, int64>> queries(q);
    int maxN = 0;

    for (auto &[n, k] : queries) {
        cin >> n >> k;
        maxN = max(maxN, n);
    }

    const int64 CAP = numeric_limits<int64>::max();
    vector<int64> length(maxN + 1);
    length[0] = static_cast<int64>(base.size());

    int saturatedAt = maxN + 1;

    for (int i = 1; i <= maxN; ++i) {
        i128 value = static_cast<i128>(prefix.size()) +
                     2 * static_cast<i128>(length[i - 1]) +
                     static_cast<i128>(middle.size()) +
                     static_cast<i128>(suffix.size());

        length[i] = value >= CAP ? CAP : static_cast<int64>(value);

        if (length[i] == CAP && saturatedAt == maxN + 1)
            saturatedAt = i;
    }

    for (auto [n, k] : queries) {
        char answer = '.';

        while (true) {
            if (n == 0) {
                if (k >= 1 && k <= static_cast<int64>(base.size()))
                    answer = base[k - 1];
                break;
            }

            if (n > saturatedAt) {
                if (k <= static_cast<int64>(prefix.size())) {
                    answer = prefix[k - 1];
                    break;
                }

                int64 levels = n - saturatedAt;
                int64 descend = min<int64>(
                    levels, (k - 1) / static_cast<int64>(prefix.size()));

                n -= static_cast<int>(descend);
                k -= descend * static_cast<int64>(prefix.size());
                continue;
            }

            if (k <= static_cast<int64>(prefix.size())) {
                answer = prefix[k - 1];
                break;
            }
            k -= prefix.size();

            if (k <= length[n - 1]) {
                --n;
                continue;
            }
            k -= length[n - 1];

            if (k <= static_cast<int64>(middle.size())) {
                answer = middle[k - 1];
                break;
            }
            k -= middle.size();

            if (k <= length[n - 1]) {
                --n;
                continue;
            }
            k -= length[n - 1];

            if (k <= static_cast<int64>(suffix.size()))
                answer = suffix[k - 1];

            break;
        }

        cout << answer;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using u64 = unsigned long long;
using i128 = __int128_t;

const string BASE =
    "What are you doing at the end of the world? Are you busy? Will you save us?";
const string PREFIX = "What are you doing while sending \"";
const string MIDDLE = "\"? Are you busy? Will you send \"";
const string SUFFIX = "\"?";
const u64 LIMIT = 4'000'000'000'000'000'000ULL;

vector<u64> lengths;

char getCharacter(int64 n, u64 pos) {
    int64 threshold = static_cast<int64>(lengths.size()) - 1;

    if (n > threshold) {
        int64 levels = n - threshold;
        i128 prefixLength = static_cast<i128>(levels) * PREFIX.size();

        if (static_cast<i128>(pos) <= prefixLength) {
            return PREFIX[(pos - 1) % PREFIX.size()];
        }

        pos -= static_cast<u64>(prefixLength);
        n = threshold;
    }

    while (n > 0) {
        if (pos <= PREFIX.size())
            return PREFIX[pos - 1];
        pos -= PREFIX.size();

        if (pos <= lengths[n - 1]) {
            --n;
            continue;
        }
        pos -= lengths[n - 1];

        if (pos <= MIDDLE.size())
            return MIDDLE[pos - 1];
        pos -= MIDDLE.size();

        if (pos <= lengths[n - 1]) {
            --n;
            continue;
        }
        pos -= lengths[n - 1];

        if (pos <= SUFFIX.size())
            return SUFFIX[pos - 1];

        return '.';
    }

    return pos <= BASE.size() ? BASE[pos - 1] : '.';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lengths.push_back(BASE.size());
    while (lengths.back() < LIMIT) {
        i128 nextLength =
            static_cast<i128>(PREFIX.size()) +
            2 * static_cast<i128>(lengths.back()) +
            MIDDLE.size() + SUFFIX.size();

        lengths.push_back(
            nextLength >= LIMIT ? LIMIT : static_cast<u64>(nextLength)
        );
    }

    int q;
    cin >> q;

    string answer;
    answer.reserve(q);

    while (q--) {
        int64 n;
        u64 pos;
        cin >> n >> pos;
        answer.push_back(getCharacter(n, pos));
    }

    cout << answer;
    return 0;
}

