    for (int i = 1; i <= maxN; ++i) {
        i128 value = (i128)PREFIX.size() + 2 * (i128)length[i - 1]
                   + MIDDLE.size() + SUFFIX.size();
        length[i] = value >= LIMIT ? LIMIT : (int64)value;
        if (length[i] == LIMIT && saturatedAt == -1)
            saturatedAt = i;
