                    result = BASE[k - 1];
                break;
            }

            if (k <= (int64)PREFIX.size()) {
                result = PREFIX[k - 1];
                break;
            }
            k -= PREFIX.size();

            if (k <= length[n - 1]) {
                --n;
                continue;
            }
            k -= length[n - 1];

            if (k <= (int64)MIDDLE.size()) {
                result = MIDDLE[k - 1];
                break;
            }
            k -= MIDDLE.size();

            if (k <= length[n - 1]) {
                --n;
                continue;
            }
            k -= length[n - 1];

            if (k <= (int64)SUFFIX.size())
                result = SUFFIX[k - 1];

            break;
        }

        answer += result;
    }

    cout << answer;
    return 0;
